8	namespace TutorFlow.Tests;
9	
10	/// <summary>
11	/// T6g: el runner de evals calcula los promedios (por pregunta y por 1.000) solo sobre las preguntas con respuesta del
12	/// modelo, no sobre las "SIN RESULTADO"; y sin EVALS_AUDITORIA elige entre &lt;raíz&gt;/logs/auditoria.jsonl y
13	/// &lt;raíz&gt;/src/TutorFlow.Api/logs/auditoria.jsonl la que exista y sea más reciente.
14	/// El runner corre como proceso real contra un HttpListener falso; cada corrida usa directorios temporales.
15	/// </summary>
16	public sealed class EvalsRespuestasYAuditoriaTests : IDisposable
17	{
18	    const string Doc = "reglamento-x.md";
19	    const string Pedido = "gemini-3.5-flash";
20	    readonly List<string> _dirs = new();
21	
22	    public void Dispose()
23	    {
24	        foreach (var d in _dirs) { try { Directory.Delete(d, true); } catch { } }
25	    }
26	
27	    string NuevoDir()
28	    {
29	        var d = Path.Combine(Path.GetTempPath(), "tf-evrsp-" + Guid.NewGuid().ToString("N"));
30	        Directory.CreateDirectory(d);
31	        _dirs.Add(d);
32	        return d;
33	    }
34	
35	    const string Estudiantes = """
36	        [ { "id": "S-1", "nombre": "Ana Uno Pérez", "programa": "Alfa", "semestre": 2 },
37	          { "id": "S-2", "nombre": "Beto Dos Gómez", "programa": "Alfa", "semestre": 3 } ]
38	        """;
39	    const string Coordinadores = """[ { "id": "K-1", "nombre": "Laura Coord", "programa": "Alfa" } ]""";
40	
41	    static string Caso(string id, string pregunta, int codigo = 200) =>
42	        $$"""{ "id": "{{id}}", "escenario": "ESC-X", "usuario": { "rol": "estudiante", "id": "S-1" }, "pregunta": "{{pregunta}}", "codigoEsperado": {{codigo}} }""";
43	
44	    (string data, string cwd) Escenario(params string[] casos)
45	    {
46	        var data = NuevoDir();
47	        Directory.CreateDirectory(Path.Combine(data, "reglamento"));
48	        Directory.CreateDirectory(Path.Combine(data, "api"));
49	        File.WriteAllText(Path.Combine(data, "reglamento", Doc), "# T\n\n## Plazos\n\ntexto\n");
50	        File.WriteAllText(Path.Combine(data, "api", "estudiantes.json"), Estudiantes);
51	        File.WriteAllText(Path.Combine(data, "api", "coordinadores.json"), Coordinadores);
52	        File.WriteAllText(Path.Combine(data, "preguntas-ejemplo.json"), "[" + string.Join(",", casos) + "]");
53	        return (data, NuevoDir());
54	    }
55	
56	    record Fila(int Codigo, int Entrada, int Salida, double Costo, string? Pedido, string[] Modelos);
57	
58	    static int PuertoLibre()
59	    {
60	        var l = new TcpListener(IPAddress.Loopback, 0);
61	        l.Start();
62	        var port = ((IPEndPoint)l.LocalEndpoint).Port;
63	        l.Stop();
64	        return port;
65	    }
66	
67	    sealed class ApiFalsa : IDisposable
68	    {
69	        readonly HttpListener _l = new();
70	        public string Url { get; }
71	
72	        public ApiFalsa(Func<string, Fila> segun, string? rutaAuditoria)
73	        {
74	            Url = $"http://localhost:{PuertoLibre()}";
75	            _l.Prefixes.Add(Url + "/");
76	            _l.Start();
77	            _ = Task.Run(async () =>
78	            {
79	                while (_l.IsListening)
80	                {
81	                    HttpListenerContext ctx;
82	                    try { ctx = await _l.GetContextAsync(); } catch { break; }
83	                    string cuerpoPeticion;
84	                    using (var sr = new StreamReader(ctx.Request.InputStream, Encoding.UTF8)) cuerpoPeticion = await sr.ReadToEndAsync();
85	                    using var doc = JsonDocument.Parse(cuerpoPeticion);
86	                    var pregunta = doc.RootElement.GetProperty("pregunta").GetString()!;
87	                    var id = doc.RootElement.GetProperty("usuario").GetProperty("id").GetString()!;
88	                    var f = segun(pregunta);
89	
90	                    if (rutaAuditoria != null)
91	                    {
92	                        var linea = JsonSerializer.Serialize(new Dictionary<string, object?>
93	                        {
94	                            ["fechaHora"] = DateTimeOffset.UtcNow.ToString("o"),
95	                            ["rol"] = "estudiante", ["id"] = id, ["pregunta"] = pregunta,
96	                            ["estudiantesConsultados"] = Array.Empty<string>(), ["citas"] = Array.Empty<object>(),
97	                            ["codigo"] = f.Codigo, ["tokens"] = f.Entrada + f.Salida, ["costoUsd"] = f.Costo,
98	                            ["modeloPedido"] = f.Pedido, ["modelosRespondidos"] = f.Modelos,
99	                            ["tokensEntrada"] = f.Entrada, ["tokensSalida"] = f.Salida,
100	                        });
101	                        File.AppendAllText(rutaAuditoria, linea + "\n", new UTF8Encoding(false));
102	                    }
103	
104	                    string cuerpo = f.Codigo == 200
105	                        ? JsonSerializer.Serialize(new
106	                        {
107	                            respuesta = "texto normal", citas = Array.Empty<object>(), usoDatosEstudiante = false,
108	                            tokens = f.Entrada + f.Salida, costoUsd = f.Costo,
109	                        })
110	                        : "{\"error\":\"fallo simulado\"}";
111	                    var bytes = Encoding.UTF8.GetBytes(cuerpo);
112	                    ctx.Response.StatusCode = f.Codigo;
113	                    ctx.Response.ContentType = "application/json";
114	                    await ctx.Response.OutputStream.WriteAsync(bytes);
115	                    ctx.Response.Close();
116	                }
117	            });
118	        }
119	
120	        public void Dispose() { try { _l.Stop(); _l.Close(); } catch { } }
121	    }
