67	    sealed class ApiFalsa : IDisposable
68	    {
69	        readonly HttpListener _l = new();
70	        public string Url { get; }
71	
72	        public ApiFalsa(Func<string, Fila> segun, string? rutaAuditoria)
73	        {
74	            Url = $"http://localhost:{PuertoLibre()}";
75	            _l.Prefixes.Add(Url + "/");
76	            _l.Start();
77	            _ = Task.Run(async () =>
78	            {
79	                while (_l.IsListening)
80	                {
81	                    HttpListenerContext ctx;
82	                    try { ctx = await _l.GetContextAsync(); } catch { break; }
83	                    string cuerpoPeticion;
84	                    using (var sr = new StreamReader(ctx.Request.InputStream, Encoding.UTF8)) cuerpoPeticion = await sr.ReadToEndAsync();
85	                    using var doc = JsonDocument.Parse(cuerpoPeticion);
86	                    var pregunta = doc.RootElement.GetProperty("pregunta").GetString()!;
87	                    var id = doc.RootElement.GetProperty("usuario").GetProperty("id").GetString()!;
88	                    var f = segun(pregunta);
89	
90	                    if (rutaAuditoria != null)
91	                    {
92	                        var linea = JsonSerializer.Serialize(new Dictionary<string, object?>
93	                        {
94	                            ["fechaHora"] = DateTimeOffset.UtcNow.ToString("o"),
95	                            ["rol"] = "estudiante", ["id"] = id, ["pregunta"] = pregunta,
96	                            ["estudiantesConsultados"] = Array.Empty<string>(), ["citas"] = Array.Empty<object>(),
97	                            ["codigo"] = f.Codigo, ["tokens"] = f.Entrada + f.Salida, ["costoUsd"] = f.Costo,
98	                            ["modeloPedido"] = f.Pedido, ["modelosRespondidos"] = f.Modelos,
99	                            ["tokensEntrada"] = f.Entrada, ["tokensSalida"] = f.Salida,
100	                        });
101	                        File.AppendAllText(rutaAuditoria, linea + "\n", new UTF8Encoding(false));
102	                    }
103	
104	                    string cuerpo = f.Codigo == 200
105	                        ? JsonSerializer.Serialize(new
106	                        {
107	                            respuesta = "texto normal", citas = Array.Empty<object>(), usoDatosEstudiante = false,
108	                            tokens = f.Entrada + f.Salida, costoUsd = f.Costo,
109	                        })
110	                        : "{\"error\":\"fallo simulado\"}";
111	                    var bytes = Encoding.UTF8.GetBytes(cuerpo);
112	                    ctx.Response.StatusCode = f.Codigo;
113	                    ctx.Response.ContentType = "application/json";
114	                    await ctx.Response.OutputStream.WriteAsync(bytes);
115	                    ctx.Response.Close();
116	                }
117	            });
118	        }
