125	    async Task<Salida> Ejecutar(string data, string cwd, string url, string? auditoria)
126	    {
127	        var dll = Path.Combine(AppContext.BaseDirectory, "TutorFlow.Evals.dll");
128	        Assert.True(File.Exists(dll), "No esta TutorFlow.Evals.dll junto a las pruebas");
129	        var psi = new ProcessStartInfo("dotnet", $"\"{dll}\"")
130	        {
131	            WorkingDirectory = cwd, RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false,
132	        };
133	        psi.Environment["EVALS_DATA"] = data;
134	        psi.Environment["EVALS_API_URL"] = url;
135	        psi.Environment["EVALS_PAUSA_MS"] = "0";
136	        psi.Environment["EVALS_ESPERA_MS"] = "1";
137	        psi.Environment["LLM_API_KEY"] = "llave-falsa-123";
138	        psi.Environment.Remove("LLM_MODEL");
139	        psi.Environment.Remove("EVALS_AUDITORIA");
140	        if (auditoria != null) psi.Environment["EVALS_AUDITORIA"] = auditoria;
141	        using var p = Process.Start(psi)!;
142	        var o = p.StandardOutput.ReadToEndAsync();
143	        var e = p.StandardError.ReadToEndAsync();
144	        using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(90));
145	        try { await p.WaitForExitAsync(cts.Token); }
146	        catch (OperationCanceledException) { try { p.Kill(true); } catch { } throw; }
147	        var texto = await o + "\n" + await e;
148	        var ruta = Path.Combine(cwd, "evals", "resultados", "ultimo.json");
149	        Assert.True(File.Exists(ruta), "El runner no escribio ultimo.json en el directorio de trabajo. Salida:\n" + texto);
150	        return new Salida(p.ExitCode, texto, JsonDocument.Parse(File.ReadAllText(ruta)).RootElement.Clone());
151	    }
