        Assert.Equal(460, resto.GetProperty("tokens").GetInt64());
        Assert.Equal(230, resto.GetProperty("tokensPromedio").GetDouble(), 6);
        Assert.Equal(2.0, resto.GetProperty("costoPor1000Usd").GetDouble(), 6);
    }
}
